        internal static string ResolveRoot(PhysicalRootToken token)
        { return token.Index < PhysicalRoots.Length ? StringAt(PhysicalRoots[token.Index].BodyTextureRoot) : null; }

        // Validates an already-resolved value; it does not select or fall back.
        // Revision equality pairs the result with its registry publication; the frozen field comparisons below validate content.
        internal static bool TryMatch(ResolvedBodyPresentation resolved, PresentationRegistry registry,
            out PhysicalRootToken root, out RegistryMatchFailure failure)
        {
            root = default(PhysicalRootToken);
            failure = new RegistryMatchFailure(RegistryMatchFailureCode.None, null);
            if (resolved == null) return Fail(RegistryMatchFailureCode.NullResolution, null, out root, out failure);
            if (registry == null) return Fail(RegistryMatchFailureCode.NullRegistry, null, out root, out failure);
            if (resolved.RegistryRevision != registry.Revision) return Fail(RegistryMatchFailureCode.RegistryRevisionMismatch, "revision", out root, out failure);
            if (resolved.IsNativeFallback || resolved.SourceEntry == null) return Fail(RegistryMatchFailureCode.NativeFallback, resolved.FallbackReason, out root, out failure);
            PresentationProfile effectiveProfile;
            if (string.IsNullOrEmpty(resolved.EffectiveProfileId) || !registry.Profiles.TryGetValue(resolved.EffectiveProfileId, out effectiveProfile))
                return Fail(RegistryMatchFailureCode.EffectiveProfileMissing, resolved.EffectiveProfileId, out root, out failure);
            if (!IsRimRoundProvider(effectiveProfile.ProviderPackageId)) return Fail(RegistryMatchFailureCode.EffectiveProfileNotRimRound, effectiveProfile.ProviderPackageId, out root, out failure);
            ResolvedStageEntry effectiveEntry;
            if (!effectiveProfile.TryGetEntry(resolved.EffectiveShapeId, resolved.EffectiveStageKey, out effectiveEntry))
                return Fail(RegistryMatchFailureCode.EffectiveEntryMissing, Join(resolved.EffectiveProfileId, resolved.EffectiveShapeId, resolved.EffectiveStageKey), out root, out failure);
            if (!object.ReferenceEquals(effectiveEntry, resolved.SourceEntry)) return Fail(RegistryMatchFailureCode.EffectiveEntryObjectMismatch, resolved.EffectiveProfileId, out root, out failure);
            if (effectiveEntry.ProfileId != resolved.EffectiveProfileId || effectiveEntry.ShapeId != resolved.EffectiveShapeId || effectiveEntry.StageKey != resolved.EffectiveStageKey)
                return Fail(RegistryMatchFailureCode.EffectiveIdentityMismatch, Join(effectiveEntry.ProfileId, effectiveEntry.ShapeId, effectiveEntry.StageKey), out root, out failure);
            int aliasIndex = FindTargetAlias(resolved.EffectiveProfileId, resolved.EffectiveShapeId, resolved.EffectiveStageKey);
            if (aliasIndex < 0) return Fail(RegistryMatchFailureCode.TargetAliasNotFrozen, Join(resolved.EffectiveProfileId, resolved.EffectiveShapeId, resolved.EffectiveStageKey), out root, out failure);
            TargetStageAlias alias = TargetAliases[aliasIndex];
            if (alias.SourceIndex >= Sources.Length) return Fail(RegistryMatchFailureCode.TerminalIdentityMismatch, "source-index", out root, out failure);
            SourceStageRecord source = Sources[alias.SourceIndex];
            if (effectiveEntry.SourceProfileId != StringAt(source.ProfileId) || effectiveEntry.SourceShapeId != StringAt(source.ShapeId) || effectiveEntry.SourceStageKey != StringAt(source.StageKey))
                return Fail(RegistryMatchFailureCode.TerminalIdentityMismatch, Join(effectiveEntry.SourceProfileId, effectiveEntry.SourceShapeId, effectiveEntry.SourceStageKey), out root, out failure);
            PresentationProfile terminalProfile;
            if (!registry.Profiles.TryGetValue(StringAt(source.ProfileId), out terminalProfile)) return Fail(RegistryMatchFailureCode.TerminalProfileMissing, StringAt(source.ProfileId), out root, out failure);
            if (!IsRimRoundProvider(terminalProfile.ProviderPackageId)) return Fail(RegistryMatchFailureCode.TerminalProfileNotRimRound, terminalProfile.ProviderPackageId, out root, out failure);
            ResolvedStageEntry terminalEntry;
            if (!terminalProfile.TryGetEntry(StringAt(source.ShapeId), StringAt(source.StageKey), out terminalEntry))
                return Fail(RegistryMatchFailureCode.TerminalEntryMissing, Join(StringAt(source.ProfileId), StringAt(source.ShapeId), StringAt(source.StageKey)), out root, out failure);
            if (terminalEntry.ProfileId != StringAt(source.ProfileId) || terminalEntry.ShapeId != StringAt(source.ShapeId) || terminalEntry.StageKey != StringAt(source.StageKey) ||
                terminalEntry.SourceProfileId != StringAt(source.ProfileId) || terminalEntry.SourceShapeId != StringAt(source.ShapeId) || terminalEntry.SourceStageKey != StringAt(source.StageKey))
                return Fail(RegistryMatchFailureCode.TerminalEntryNotTerminal, Join(terminalEntry.SourceProfileId, terminalEntry.SourceShapeId, terminalEntry.SourceStageKey), out root, out failure);
            PresentationGeometry geometry = Geometries[source.GeometryIndex];
            if (geometry.BodyTextureRoot >= PhysicalRoots.Length) return Fail(RegistryMatchFailureCode.GeometryMismatch, "BodyTextureRoot.index", out root, out failure);
            string mismatch;
            if (!GeometryMatches(effectiveEntry, geometry, out mismatch)) return Fail(RegistryMatchFailureCode.GeometryMismatch, "effective." + mismatch, out root, out failure);
            if (!GeometryMatches(terminalEntry, geometry, out mismatch)) return Fail(RegistryMatchFailureCode.GeometryMismatch, "terminal." + mismatch, out root, out failure);
            root = new PhysicalRootToken(geometry.BodyTextureRoot);
            return true;
        }
        private static bool IsRimRoundProvider(string provider)
        { return string.Equals(provider, RimRoundProviderPackageId, StringComparison.OrdinalIgnoreCase); }
        private static string Join(string profile, string shape, string stage)
        { return (profile ?? "<null>") + "/" + (shape ?? "<null>") + "/" + (stage ?? "<null>"); }
        private static bool Fail(RegistryMatchFailureCode code, string detail, out PhysicalRootToken root, out RegistryMatchFailure failure)
        { root = default(PhysicalRootToken); failure = new RegistryMatchFailure(code, detail); return false; }
        private static int FindTargetAlias(string profile, string shape, string stage)
        {
            int low = 0, high = TargetAliases.Length - 1;
            while (low <= high)
            {
                int mid = low + ((high - low) / 2);
                TargetStageAlias row = TargetAliases[mid];
                int compare = string.CompareOrdinal(profile, StringAt(row.ProfileId));
                if (compare == 0) compare = string.CompareOrdinal(shape, StringAt(row.ShapeId));
                if (compare == 0) compare = string.CompareOrdinal(stage, StringAt(row.StageKey));
                if (compare == 0) return mid;
                if (compare < 0) high = mid - 1; else low = mid + 1;
            }
            return -1;
        }
        private static bool GeometryMatches(ResolvedStageEntry actual, PresentationGeometry expected, out string mismatch)
        {
            mismatch = null;
            if (!string.Equals(actual.BodyTextureRoot, StringAt(PhysicalRoots[expected.BodyTextureRoot].BodyTextureRoot), StringComparison.Ordinal)) { mismatch = "BodyTextureRoot"; return false; }
            if (((expected.DirectionPolicy == SilhouetteDirectionPolicy.MirrorWest && actual.DirectionPolicy != "mirrorWest") || (expected.DirectionPolicy == SilhouetteDirectionPolicy.FourDirections && actual.DirectionPolicy != "fourDirections"))) { mismatch = "DirectionPolicy"; return false; }
            if (((expected.ShaderPolicy == SilhouetteShaderPolicy.Cutout && actual.ShaderPolicy != "cutout") || (expected.ShaderPolicy == SilhouetteShaderPolicy.Masked && actual.ShaderPolicy != "masked"))) { mismatch = "ShaderPolicy"; return false; }
            if (((expected.ColorPolicy == SilhouetteColorPolicy.Skin && actual.ColorPolicy != "skin") || (expected.ColorPolicy == SilhouetteColorPolicy.White && actual.ColorPolicy != "white"))) { mismatch = "ColorPolicy"; return false; }
            if (!string.Equals(actual.MaskTextureRoot, StringAt(expected.MaskTextureRoot), StringComparison.Ordinal)) { mismatch = "MaskTextureRoot"; return false; }
            if (((expected.MaskPolicy == SilhouetteMaskPolicy.None && actual.MaskPolicy != "none") || (expected.MaskPolicy == SilhouetteMaskPolicy.BodySuffix && actual.MaskPolicy != "bodySuffix") || (expected.MaskPolicy == SilhouetteMaskPolicy.Separate && actual.MaskPolicy != "separate"))) { mismatch = "MaskPolicy"; return false; }
            if (actual.MapScale != expected.MapScale) { mismatch = "MapScale"; return false; }
            if (actual.PortraitScale != expected.PortraitScale) { mismatch = "PortraitScale"; return false; }
            if (actual.PortraitZoom != expected.PortraitZoom) { mismatch = "PortraitZoom"; return false; }
            if (actual.PortraitPanX != expected.PortraitPanX) { mismatch = "PortraitPanX"; return false; }
            if (actual.PortraitPanY != expected.PortraitPanY) { mismatch = "PortraitPanY"; return false; }
            if (actual.PortraitPanStyleY != expected.PortraitPanStyleY) { mismatch = "PortraitPanStyleY"; return false; }
            if (actual.ForceFittedPortrait != expected.ForceFittedPortrait) { mismatch = "ForceFittedPortrait"; return false; }
            if (((expected.DownedPosePolicy == SilhouetteDownedPosePolicy.Native && actual.DownedPosePolicy != "native") || (expected.DownedPosePolicy == SilhouetteDownedPosePolicy.FrontStatic && actual.DownedPosePolicy != "frontStatic"))) { mismatch = "DownedPosePolicy"; return false; }
            if (((expected.AnchorPolicy == SilhouetteAnchorPolicy.Native && actual.AnchorPolicy != "native") || (expected.AnchorPolicy == SilhouetteAnchorPolicy.LegacyBodyType && actual.AnchorPolicy != "legacyBodyType") || (expected.AnchorPolicy == SilhouetteAnchorPolicy.Explicit && actual.AnchorPolicy != "explicit"))) { mismatch = "AnchorPolicy"; return false; }
            if (!string.Equals(actual.LegacyBodyTypeDefName, StringAt(expected.LegacyBodyTypeDefName), StringComparison.Ordinal)) { mismatch = "LegacyBodyTypeDefName"; return false; }
            if (actual.HeadOffsetX != expected.HeadOffsetX) { mismatch = "HeadOffsetX"; return false; }
            if (actual.HeadOffsetY != expected.HeadOffsetY) { mismatch = "HeadOffsetY"; return false; }
            if (actual.NorthOffsetX != expected.NorthOffsetX) { mismatch = "NorthOffsetX"; return false; }
            if (actual.NorthOffsetY != expected.NorthOffsetY) { mismatch = "NorthOffsetY"; return false; }
            if (actual.BedOffsetX != expected.BedOffsetX) { mismatch = "BedOffsetX"; return false; }
            if (actual.BedOffsetY != expected.BedOffsetY) { mismatch = "BedOffsetY"; return false; }
            if (actual.WoundOffsetX != expected.WoundOffsetX) { mismatch = "WoundOffsetX"; return false; }
            if (actual.WoundOffsetY != expected.WoundOffsetY) { mismatch = "WoundOffsetY"; return false; }
            if (actual.EyeOffsetX != expected.EyeOffsetX) { mismatch = "EyeOffsetX"; return false; }
            if (actual.EyeOffsetY != expected.EyeOffsetY) { mismatch = "EyeOffsetY"; return false; }
            if (!string.Equals(actual.ApparelSuffix, StringAt(expected.ApparelSuffix), StringComparison.Ordinal)) { mismatch = "ApparelSuffix"; return false; }
            if (((expected.ApparelFallback == SilhouetteApparelFallback.Requested && actual.ApparelFallback != "requested") || (expected.ApparelFallback == SilhouetteApparelFallback.Default && actual.ApparelFallback != "default") || (expected.ApparelFallback == SilhouetteApparelFallback.Native && actual.ApparelFallback != "native"))) { mismatch = "ApparelFallback"; return false; }
            if (((expected.CorpsePolicy == SilhouetteCorpsePolicy.Native && actual.CorpsePolicy != "native") || (expected.CorpsePolicy == SilhouetteCorpsePolicy.Body && actual.CorpsePolicy != "body"))) { mismatch = "CorpsePolicy"; return false; }
            if (((expected.DessicationPolicy == SilhouetteDessicationPolicy.Native && actual.DessicationPolicy != "native") || (expected.DessicationPolicy == SilhouetteDessicationPolicy.Body && actual.DessicationPolicy != "body"))) { mismatch = "DessicationPolicy"; return false; }
            if (actual.WiggleSpeed != expected.WiggleSpeed) { mismatch = "WiggleSpeed"; return false; }
            return true;
        }
    }
